import{_ as t,o,c as a,ag as i}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 15 homework — Ready to ship","description":"","frontmatter":{"source":"weeks/15-ship-it/homework.md"},"headers":[],"relativePath":"weeks/15-ship-it/homework.md","filePath":"weeks/15-ship-it/homework.md"}'),r={name:"weeks/15-ship-it/homework.md"};function s(n,e,h,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="week-15-homework--ready-to-ship" tabindex="-1">Week 15 homework — Ready to ship <a class="header-anchor" href="#week-15-homework--ready-to-ship" aria-label="Permalink to &quot;Week 15 homework — Ready to ship&quot;">​</a></h1><blockquote><p><strong>Due before the Project Fair</strong> (finals week has no Studio A; the Fair&#39;s day and time are on Canvas, the course&#39;s learning management system). Your app must be live, polished and documented for the Fair. About <strong>5.5 hours</strong>. Deploying and polishing always take longer than coding, so start early. Work in the <a href="./../../resources/safe-loop.html">Safe Loop</a>; commit as you go. The final submission comes in two parts (<a href="./../16-project-fair/">week 16</a>): the product (the <code>v1.0</code> release and the Canvas links) at the start of the Project Fair, and your final reflection and revised AI-use rules by the end of finals week.</p></blockquote><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><p>When every box is ticked, your capstone is ready for the Fair, and the final submission is mostly a matter of tagging and handing in.</p><ul><li>☐ <strong>Polish checklist</strong> sections 1–7 ticked on your live site, or each unticked item says why it doesn&#39;t apply (<a href="./polish-checklist.html">Polish checklist</a>).</li><li>☐ <strong>Production URL</strong> works in a fresh browser (a private window), on a phone and a laptop. Vercel deletes old preview deployments, so only the production URL counts.</li><li>☐ <strong>Repo:</strong> public on your GitHub account, with a history of small commits, including before and after agent tasks, with <code>Assisted-by:</code> lines.</li><li>☐ <strong>README.md</strong> from the <a href="./../../templates/PROJECT_README.html">README template</a>: what it does, production URL, demo video link, a screenshot, how to run it, how it works, the &quot;Authorization is enforced in: …&quot; line, where each key lives, status against the spec, an honest <strong>Known issues</strong> section, the tools you used and any fallback you switched to, and credits. Pairs: a Contributions table.</li><li>☐ <strong>SPEC.md</strong> with the acceptance-criteria table marked pass, partial or fail.</li><li>☐ <strong>AGENTS.md</strong> current with how the project actually works, including its Scope section and trial notes.</li><li>☐ <strong>PROMPTS.md:</strong> an honest log, with a teach-back before every agent commit and your ownership statement (&quot;what I wrote or decided myself&quot;), including this week&#39;s hand-written fix.</li><li>☐ <strong>TESTS.md:</strong> at least 3 automated tests (<code>npm test</code> passes) and at least 3 manual edge-case tests with dated results.</li><li>☐ <strong>SECURITY_CHECKLIST.md:</strong> complete, with evidence, dated this week.</li><li>☐ <strong>At least two</strong> feature types working (<a href="./../../projects/capstone.html#feature-types-include-at-least-two">capstone brief</a>). Pairs: three, or two plus the approved scope increase.</li><li>☐ <strong>Demo video:</strong> 2–3 minutes, with captions or a transcript, linked in the README (or submitted on Canvas).</li><li>☐ <strong>Fair ready:</strong> a station sign, a practiced pitch, your Supabase project awake.</li><li>☐ <strong>Weekly reflection</strong> on Canvas (🔴 AI off).</li></ul><table tabindex="0"><thead><tr><th>Part</th><th>Time</th></tr></thead><tbody><tr><td>1. Finish the polish checklist</td><td>about 2 h</td></tr><tr><td>2. Finish the demo video</td><td>about 1 h</td></tr><tr><td>3. Bring the documents up to date</td><td>about 1.5 h</td></tr><tr><td>4. Get ready for the Fair</td><td>about 0.5 h</td></tr><tr><td>5. Weekly reflection and <code>PROMPTS.md</code></td><td>about 0.5 h</td></tr><tr><td><strong>Total</strong></td><td><strong>about 5.5 h</strong></td></tr></tbody></table><h2 id="core-tier-required" tabindex="-1">Core tier (required) <a class="header-anchor" href="#core-tier-required" aria-label="Permalink to &quot;Core tier (required)&quot;">​</a></h2><h3 id="1-finish-the-polish-checklist-about-2-h" tabindex="-1">1. Finish the polish checklist (about 2 h) <a class="header-anchor" href="#1-finish-the-polish-checklist-about-2-h" aria-label="Permalink to &quot;1. Finish the polish checklist (about 2 h)&quot;">​</a></h3><p>🟢 AI on for fixes, in the Safe Loop. Finish sections 1–7 of the <a href="./polish-checklist.html">Polish checklist</a> on your <strong>live</strong> site: the three states, phone, title and favicon, accessibility (including the keyboard test), copy, the README with Known issues, and the final technical pass. Where a fix is pure logic, write the automated test first. Commit after each fix and check the production URL after each push.</p><p>✅ <strong>Done when:</strong> sections 1–7 are ticked, or each unticked item says why it doesn&#39;t apply.</p><h3 id="2-finish-the-demo-video-about-1-h" tabindex="-1">2. Finish the demo video (about 1 h) <a class="header-anchor" href="#2-finish-the-demo-video-about-1-h" aria-label="Permalink to &quot;2. Finish the demo video (about 1 h)&quot;">​</a></h3><p>Finish what you recorded in <a href="./lab.html#part-b3--record-your-demo-video-core-25-min">Studio B Part B3</a>: check it&#39;s 2–3 minutes, add or correct captions (or write the transcript), check no secret or real personal data appears, upload it unlisted, and link it in your README. Or submit it on Canvas only and write &quot;Demo video: submitted on Canvas&quot; in the README: a link in a public README can be found by anyone. If recording or speaking is a barrier, a written script with screenshots is accepted instead (<a href="./../../assessment/#accommodations">accommodations</a>).</p><h3 id="3-bring-the-documents-up-to-date-about-15-h" tabindex="-1">3. Bring the documents up to date (about 1.5 h) <a class="header-anchor" href="#3-bring-the-documents-up-to-date-about-15-h" aria-label="Permalink to &quot;3. Bring the documents up to date (about 1.5 h)&quot;">​</a></h3><p>Every document in the checklist above must match the app as it is now, not as you planned it. Read each one against the live app. Mark each acceptance criterion in <code>SPEC.md</code> pass, partial or fail; update <code>AGENTS.md</code> if the agent&#39;s scope changed; add the dated results of your manual tests to <code>TESTS.md</code>. Run <code>npm test</code> and <code>npm run check:secrets</code> one last time and date the evidence in <code>SECURITY_CHECKLIST.md</code>.</p><p>✅ <strong>Done when:</strong> a classmate could use your app from the URL and run it from the README alone.</p><h3 id="4-get-ready-for-the-fair-about-05-h" tabindex="-1">4. Get ready for the Fair (about 0.5 h) <a class="header-anchor" href="#4-get-ready-for-the-fair-about-05-h" aria-label="Permalink to &quot;4. Get ready for the Fair (about 0.5 h)&quot;">​</a></h3><p>Make a sign or sticky note with your app&#39;s name and production URL or a QR code. Apply the note your partner gave you in the rehearsal, and practice your 60–90 second pitch (problem → quick demo → one thing you&#39;re proud of → one known issue). Read <a href="./../16-project-fair/project-fair.html">What each presenter brings</a>, and open your Supabase project the day before the Fair so it isn&#39;t paused.</p><h3 id="5-weekly-reflection-and-promptsmd-about-05-h" tabindex="-1">5. Weekly reflection and <code>PROMPTS.md</code> (about 0.5 h) <a class="header-anchor" href="#5-weekly-reflection-and-promptsmd-about-05-h" aria-label="Permalink to &quot;5. Weekly reflection and `PROMPTS.md` (about 0.5 h)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> Bring <code>PROMPTS.md</code> up to date, then write about 200 words on Canvas, never in your repo:</p><ol><li>Name one thing you found only by testing the <strong>live</strong> site (not localhost), and what you did about it.</li><li>Pick one item in your Known issues section. Why did you name it rather than fix it?</li><li>Look ahead to the final reflection: note two or three concrete moments from the course when you <em>felt</em> you understood something, and say whether you could actually explain it later.</li></ol><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><ul><li>Add one accessibility win beyond the checklist: a skip link, or a reduced-motion option if you use animation.</li><li>Run your browser&#39;s Lighthouse audit on the production URL and fix its top accessibility item.</li><li>Turn an edge case you found while polishing into an automated test.</li><li>Write a short &quot;what I&#39;d build next&quot; note in your README&#39;s Next steps.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Supabase free projects pause when nobody uses them (<a href="./../../TOOLS.html">Tool Handout</a>). Restore yours before the Fair and check the production URL still works (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>).</p></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> before the Fair, your main user story works at the production URL, your README has an honest Known issues section, and your demo video is recorded. Without a working production URL the capstone is capped until it runs, so if you&#39;re behind, ship the smallest honest version (one working feature, deployed, documented, with known issues named) and tell your instructor before the Fair.</p></div>',24)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
